366	    /**
367	     * The narrowest type for the type parameter n whose arguments are vals, or
368	     * null: among the arguments' types, the types they coerce to and n's
369	     * bounds, and with supertypes the arguments' supertypes as well, those
370	     * that each argument is a subtype of or coerces to and that n's bounds
371	     * admit, the one that is a subtype of every other or coerces to it.
372	     */
373	    private static FType narrowest(String n, List<FValue> vals,
374	                                   BoundingMap<String, FType, TypeLatticeOps> abm,
375	                                   List<StaticParam> rechecks, Set<String> tp_set, Environment env,
376	                                   List<FType> bounds, Environment within, boolean supertypes) {
377	        LinkedHashSet<FType> candidates = new LinkedHashSet<FType>();
378	        for (FValue v : vals) {
379	            if (supertypes) candidates.addAll(v.type().getTransitiveExtends());
380	            else candidates.add(v.type());
381	        }
382	        for (FValue v : vals) candidates.addAll(Coercions.coercionTargets(v, within));
383	        if (bounds != null) candidates.addAll(bounds);
384	        List<FType> admitted = new ArrayList<FType>();
385	        for (FType c : candidates) {
386	            if (c instanceof BottomType || c instanceof FTypeTop) continue;
387	            boolean all = true;
388	            for (FValue v : vals) {
389	                if (!Coercions.admits(c, v)) {
390	                    all = false;
391	                    break;
392	                }
393	            }
394	            if (!all) continue;
395	            BoundingMap<String, FType, TypeLatticeOps> trial = abm.copy();
396	            try {
397	                trial.joinPut(n, c);
398	                for (StaticParam tp : rechecks) {
399	                    if (!NodeUtil.getName(tp).equals(n)) continue;
400	                    for (Type tr : tp.getExtendsClause()) c.unify(env, tp_set, trial, tr);
401	                }
402	            }
403	            catch (FortressException ex) {
404	                continue;
405	            }
406	            catch (EmptyLatticeIntervalError ex) {
407	                continue;
408	            }
409	            admitted.add(c);
410	        }
411	        FType best = null;
412	        for (FType c : admitted) {
413	            boolean narrower = true;
414	            for (FType d : admitted) {
415	                if (d != c && !c.subtypeOf(d) && !Coercions.convertsInto(c, d)) {
416	                    narrower = false;
417	                    break;
418	                }
419	            }
420	            if (narrower) {
421	                if (best != null && best != c) return null;
422	                best = c;
423	            }
424	        }
425	        return best;
426	    }
